  async function api(url,opt={}){const headers={...(opt.headers||{})};if(state.token)headers.Authorization='Bearer '+state.token;const r=await fetch(url,{...opt,headers});let data;try{data=await r.json()}catch{data={ok:false,error:await r.text()}}if(r.status===401){logout();throw new Error('Sesión vencida')}if(!r.ok||data.ok===false)throw new Error(data.error||'Error');return data}
